import dspy
from dspy.utils.exceptions import ContextWindowExceededError


def echo(text: str) -> str:
    return f"Echoed: {text}"


class FakeReact:
    def __init__(self):
        self.calls = 0

    def __call__(self, **kwargs):
        self.calls += 1
        if self.calls == 1:
            return dspy.Prediction(next_thought="first", next_tool_name="echo", next_tool_args={"text": "one"})
        if self.calls == 2:
            return dspy.Prediction(next_thought="second", next_tool_name="echo", next_tool_args={"text": "two"})
        raise AssertionError("ReAct planner should only be called twice in this harness")


class FakeExtract:
    def __init__(self):
        self.calls = 0

    def __call__(self, **kwargs):
        self.calls += 1
        if self.calls == 1:
            raise ContextWindowExceededError(model="dummy")
        return dspy.Prediction(output_text="done")


agent = dspy.ReAct("input_text -> output_text", tools=[echo], max_iters=2)
agent.react = FakeReact()
agent.extract = FakeExtract()

result = agent(input_text="hello")

print("FINAL TRAJECTORY:", result.trajectory)
print("OUTPUT:", result.output_text)

assert list(result.trajectory.keys()) == [
    "thought_1",
    "tool_name_1",
    "tool_args_1",
    "observation_1",
]
assert result.trajectory["tool_name_1"] == "echo"
assert result.trajectory["tool_args_1"] == {"text": "two"}
assert result.trajectory["observation_1"] == "Echoed: two"
assert result.output_text == "done"
